package com.mahesh.empleave.leave;import com.mahesh.empleave.common.dto.*;import com.mahesh.empleave.user.*;import jakarta.validation.constraints.*;import lombok.*;import org.springframework.data.domain.*;import org.springframework.security.access.prepost.*;import org.springframework.security.core.*;import org.springframework.web.bind.annotation.*;import java.time.*;@RestController @RequestMapping("/api/leaves") @RequiredArgsConstructor public class LeaveController{private final LeaveService service;private final LeaveRepository repo;private final UserRepository users;record Apply(@NotBlank @Size(max=80) String leaveType,@NotNull LocalDate startDate,@NotNull LocalDate endDate,@NotBlank @Size(max=500) String reason){}record Review(@NotBlank @Size(max=500) String reason){}private PageRequest pageRequest(int page,int size){return PageRequest.of(Math.max(page,0),Math.min(Math.max(size,1),100),Sort.by("id").descending());}@PostMapping ApiDtos.Leave apply(Authentication a,@RequestBody @jakarta.validation.Valid Apply x){return ApiDtos.leave(service.apply(a.getName(),x.leaveType(),x.startDate(),x.endDate(),x.reason()));}@GetMapping("/my") Page<ApiDtos.Leave> mine(Authentication a,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="25") int size){return repo.findByApplicantOrderByIdDesc(users.findByEmail(a.getName()).orElseThrow(),pageRequest(page,size)).map(ApiDtos::leave);}@GetMapping("/pending") @PreAuthorize("hasAnyRole('MANAGER','ADMIN')") Page<ApiDtos.Leave> pending(Authentication a,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="25") int size){var u=users.findByEmail(a.getName()).orElseThrow();var all=repo.findByStatus(LeaveStatus.PENDING);var allowed=u.getRole()==Role.ADMIN?all:all.stream().filter(x->x.getApplicant().getManager()!=null&&x.getApplicant().getManager().getId().equals(u.getId())).toList();var request=pageRequest(page,size);int from=Math.min((int)request.getOffset(),allowed.size()),to=Math.min(from+request.getPageSize(),allowed.size());return new PageImpl<>(allowed.subList(from,to).stream().map(ApiDtos::leave).toList(),request,allowed.size());}@GetMapping("/{id}") ApiDtos.Leave one(Authentication a,@PathVariable Long id){var item=repo.findById(id).orElseThrow();var u=users.findByEmail(a.getName()).orElseThrow();if(!item.getApplicant().getId().equals(u.getId())&&u.getRole()!=Role.ADMIN&&(item.getApplicant().getManager()==null||!item.getApplicant().getManager().getId().equals(u.getId())))throw new SecurityException("Access denied");return ApiDtos.leave(item);}@PutMapping("/{id}/approve") @PreAuthorize("hasAnyRole('MANAGER','ADMIN')") ApiDtos.Leave approve(Authentication a,@PathVariable Long id){return ApiDtos.leave(service.approve(a.getName(),id));}@PutMapping("/{id}/reject") @PreAuthorize("hasAnyRole('MANAGER','ADMIN')") ApiDtos.Leave reject(Authentication a,@PathVariable Long id,@RequestBody @jakarta.validation.Valid Review r){return ApiDtos.leave(service.reject(a.getName(),id,r.reason()));}@PutMapping("/{id}/cancel") ApiDtos.Leave cancel(Authentication a,@PathVariable Long id){return ApiDtos.leave(service.cancel(a.getName(),id));}@GetMapping("/team") @PreAuthorize("hasAnyRole('MANAGER','ADMIN')") Page<ApiDtos.Leave> team(Authentication a,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="25") int size){var u=users.findByEmail(a.getName()).orElseThrow();var request=pageRequest(page,size);return (u.getRole()==Role.ADMIN?repo.findAll(request):repo.findByApplicantManagerOrderByIdDesc(u,request)).map(ApiDtos::leave);}}
